as color.","alternatives":[{"id":"01a218f9-372e-7d28-b9db-cf30fa110027","description":"Red","correct_answer":true},{"id":"01a218f9-372e-7520-9246-a5d9a56a629a","description":"Orange","correct_answer":false},{"id":"01a218f9-372e-73df-973e-68c45caf4830","description":"Blue","correct_answer":false},{"id":"01a218f9-372e-7017-8c8b-61b05fc56c04","description":"Purple","correct_answer":false}]},{"id":"01a218f9-372e-7c56-bd0f-de68d47008a5","locale":"en-US","category":"01a21312-b489-7dd6-93ca-116c8464996a","question":"Totems are most commonly associated with which of the following?","difficulty":1,"explanation":"Totems are associated with Indigenous cultures, though traditions vary widely among Indigenous peoples; some Northwest Coast peoples, for example, carve totem poles linked to family histories.","alternatives":[{"id":"01a218f9-372e-7d29-8a58-46e6a6b0cbd3","description":"Indigenous cultures","correct_answer":true},{"id":"01a218f9-372e-7377-bccc-bd3752e33070","description":"Modern corporations","correct_answer":false},{"id":"01a218f9-372e-7193-ac74-b6abfca03b57","description":"Ancient Greek city-states","correct_answer":false},{"id":"01a218f9-372e-75e7-8174-d6f9b4bf718c","description":"Medieval European guilds","correct_answer":false}]},{"id":"01a218f9-372e-7076-9232-3151b3ef9ce0","locale":"en-US","category":"01a21312-b489-7dd6-93ca-116c8464996a","question":"What is the traditional color associated with St. Patrick\'s Day?","difficulty":1,"explanation":"Green is linked to the shamrock and Ireland\u2019s nickname, the Emerald Isle. Wearing it is a popular St. Patrick\u2019s Day custom.","alternatives":[{"id":"01a218f9-372e-73eb-82b0-272ef926c70f","description":"Green","correct_answer":true},{"id":"01a218f9-372e-7571-8b72-a66654eced7e","description":"Blue","correct_answer":false},{"id":"01a218f9-372e-7f2d-b370-a5b3858839d3","description":"Red","correct_answer":false},{"id":"01a218f9-372e-77c4-948f-56f25232a3ab","description":"Yellow","correct_answer":false}]},{"id":"01a21